def crypto_stego_suite():
    blood_banner()

    import base64
    import hashlib
    import secrets
    import string
    import os
    import binascii
    from cryptography.fernet import Fernet
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2
    from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    from cryptography.hazmat.backends import default_backend
    from PIL import Image
    import numpy as np
    import wave
    import stepic
    from colorama import Fore, Style, init

    init()
    R = Fore.RED
    G = Fore.GREEN
    Y = Fore.YELLOW
    C = Fore.CYAN
    RESET = Style.RESET_ALL

    def encryption_tools():
        while True:
            print(f"\n{R}╔════════════════════════════════════╗{RESET}")
            print(f"{R}║       {G}ENCRYPTION TOOLS{RESET}            {R}║{RESET}")
            print(f"{R}╠════════════════════════════════════╣{RESET}")
            print(f"{R}║  {R}1){RESET} {G}AES-256 Encrypt/Decrypt{RESET}    {R}║{RESET}")
            print(f"{R}║  {R}2){RESET} {G}RSA Operations{RESET}             {R}║{RESET}")
            print(f"{R}║  {R}3){RESET} {G}Fernet (Symmetric){RESET}        {R}║{RESET}")
            print(f"{R}║  {R}4){RESET} {G}Caesar Cipher{RESET}            {R}║{RESET}")
            print(f"{R}║  {R}5){RESET} {G}Vigenère Cipher{RESET}          {R}║{RESET}")
            print(f"{R}║  {R}6){RESET} {G}Base64/32/85{RESET}             {R}║{RESET}")
            print(f"{R}║  {R}7){RESET} {G}XOR Cipher{RESET}               {R}║{RESET}")
            print(f"{R}║  {R}8){RESET} {G}Back{RESET}                     {R}║{RESET}")
            print(f"{R}╚════════════════════════════════════╝{RESET}")

            choice = input(f"\n{C}Select{R}: {RESET}")

            if choice == "1":
                # AES-256 Encryption
                print(f"\n{Y}[*]{RESET} AES-256-GCM Mode")
                action = input(f"{Y}Encrypt or Decrypt? (e/d){R}: {RESET}")

                if action == "e":
                    message = input(f"{Y}Message{R}: {RESET}").encode()
                    password = input(f"{Y}Password{R}: {RESET}").encode()

                    # Generate key from password
                    salt = os.urandom(16)
                    kdf = PBKDF2(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=100000)
                    key = kdf.derive(password)

                    # Encrypt
                    iv = os.urandom(16)
                    cipher = Cipher(algorithms.AES(key), modes.GCM(iv), backend=default_backend())
                    encryptor = cipher.encryptor()
                    ciphertext = encryptor.update(message) + encryptor.finalize()

                    # Combine salt + iv + tag + ciphertext
                    encrypted = salt + iv + encryptor.tag + ciphertext
                    result = base64.b64encode(encrypted).decode()

                    print(f"\n{G}[+]{RESET} Encrypted (Base64):")
                    print(f"{C}{result}{RESET}")

                elif action == "d":
                    encrypted = input(f"{Y}Encrypted text (Base64){R}: {RESET}")
                    password = input(f"{Y}Password{R}: {RESET}").encode()

                    try:
                        data = base64.b64decode(encrypted)
                        salt, iv, tag, ciphertext = data[:16], data[16:32], data[32:48], data[48:]

                        # Derive key
                        kdf = PBKDF2(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=100000)
                        key = kdf.derive(password)

                        # Decrypt
                        cipher = Cipher(algorithms.AES(key), modes.GCM(iv, tag), backend=default_backend())
                        decryptor = cipher.decryptor()
                        plaintext = decryptor.update(ciphertext) + decryptor.finalize()

                        print(f"\n{G}[+]{RESET} Decrypted:")
                        print(f"{C}{plaintext.decode()}{RESET}")
                    except:
                        print(f"{R}[-]{RESET} Decryption failed - wrong password or corrupted data")

            elif choice == "3":
                # Fernet symmetric encryption
                action = input(f"{Y}Generate key, Encrypt, or Decrypt? (g/e/d){R}: {RESET}")

                if action == "g":
                    key = Fernet.generate_key()
                    print(f"{G}[+]{RESET} Key: {C}{key.decode()}{RESET}")
                    print(f"{Y}[!]{RESET} Save this key safely!")

                elif action == "e":
                    key = input(f"{Y}Fernet key{R}: {RESET}").encode()
                    message = input(f"{Y}Message{R}: {RESET}").encode()
                    f = Fernet(key)
                    token = f.encrypt(message)
                    print(f"\n{G}[+]{RESET} Encrypted:")
                    print(f"{C}{token.decode()}{RESET}")

                elif action == "d":
                    key = input(f"{Y}Fernet key{R}: {RESET}").encode()
                    token = input(f"{Y}Encrypted token{R}: {RESET}").encode()
                    f = Fernet(key)
                    try:
                        decrypted = f.decrypt(token)
                        print(f"\n{G}[+]{RESET} Decrypted:")
                        print(f"{C}{decrypted.decode()}{RESET}")
                    except:
                        print(f"{R}[-]{RESET} Invalid token or key")

            elif choice == "4":
                # Caesar Cipher
                text = input(f"{Y}Text{R}: {RESET}")
                shift = int(input(f"{Y}Shift (1-25){R}: {RESET}"))
                action = input(f"{Y}Encrypt or Decrypt? (e/d){R}: {RESET}")

                result = ""
                for char in text:
                    if char.isalpha():
                        base = ord('A') if char.isupper() else ord('a')
                        if action == "e":
                            result += chr((ord(char) - base + shift) % 26 + base)
                        else:
                            result += chr((ord(char) - base - shift) % 26 + base)
                    else:
                        result += char

                print(f"\n{G}[+]{RESET} Result: {C}{result}{RESET}")

            elif choice == "5":
                # Vigenère Cipher
                def vigenere(text, key, encrypt=True):
                    result = ""
                    key_length = len(key)
                    key_as_int = [ord(i) for i in key]
                    text_int = [ord(i) for i in text]
                    for i in range(len(text_int)):
                        if encrypt:
                            value = (text_int[i] + key_as_int[i % key_length]) % 256
                        else:
                            value = (text_int[i] - key_as_int[i % key_length]) % 256
                        result += chr(value)
                    return result

                text = input(f"{Y}Text{R}: {RESET}")
                key = input(f"{Y}Key (word){R}: {RESET}")
                action = input(f"{Y}Encrypt or Decrypt? (e/d){R}: {RESET}")

                if action == "e":
                    # Convert to base64 first to handle binary
                    text = base64.b64encode(text.encode()).decode()
                    result = vigenere(text, key, True)
                    print(f"\n{G}[+]{RESET} Encrypted: {C}{result}{RESET}")
                else:
                    result = vigenere(text, key, False)
                    try:
                        result = base64.b64decode(result).decode()
                        print(f"\n{G}[+]{RESET} Decrypted: {C}{result}{RESET}")
                    except:
                        print(f"{R}[-]{RESET} Invalid key or corrupted data")

            elif choice == "7":
                # XOR Cipher
                text = input(f"{Y}Text{R}: {RESET}")
                key = input(f"{Y}Key{R}: {RESET}")

                result = ""
                for i in range(len(text)):
                    result += chr(ord(text[i]) ^ ord(key[i % len(key)]))

                # نمایش به صورت هگز برای خوانایی بهتر
                hex_result = binascii.hexlify(result.encode()).decode()
                print(f"\n{G}[+]{RESET} XOR Result (Hex): {C}{hex_result}{RESET}")
                print(f"{Y}[*]{RESET} To decrypt, XOR again with same key")

            elif choice == "8":
                break

    def steganography_tools():
        while True:
            print(f"\n{R}╔════════════════════════════════════╗{RESET}")
            print(f"{R}║      {G}STEGANOGRAPHY TOOLS{RESET}         {R}║{RESET}")
            print(f"{R}╠════════════════════════════════════╣{RESET}")
            print(f"{R}║  {R}1){RESET} {G}Hide in Image (PIL){RESET}        {R}║{RESET}")
            print(f"{R}║  {R}2){RESET} {G}Extract from Image{RESET}         {R}║{RESET}")
            print(f"{R}║  {R}3){RESET} {G}Hide in Audio (WAV){RESET}       {R}║{RESET}")
            print(f"{R}║  {R}4){RESET} {G}Extract from Audio{RESET}         {R}║{RESET}")
            print(f"{R}║  {R}5){RESET} {G}Text Steganography (Zero-Width){RESET} {R}║{RESET}")
            print(f"{R}║  {R}6){RESET} {G}Back{RESET}                       {R}║{RESET}")
            print(f"{R}╚════════════════════════════════════╝{RESET}")

            choice = input(f"\n{C}Select{R}: {RESET}")

            if choice == "1":
                # مخفی کردن پیام در تصویر با LSB
                image_path = input(f"{Y}Cover image path{R}: {RESET}")
                message = input(f"{Y}Secret message{R}: {RESET}")
                output_path = input(f"{Y}Output image path{R}: {RESET}")

                try:
                    img = Image.open(image_path)
                    # تبدیل پیام به باینری
                    binary_msg = ''.join(format(ord(i), '08b') for i in message)
                    binary_msg += '1111111111111110'  # delimiter

                    pixels = np.array(img)
                    if len(pixels.shape) == 3:
                        height, width, channels = pixels.shape
                    else:
                        height, width = pixels.shape
                        channels = 1

                    idx = 0
                    for i in range(height):
                        for j in range(width):
                            if channels > 1:
                                for k in range(3):  # R, G, B
                                    if idx < len(binary_msg):
                                        pixels[i, j, k] = (pixels[i, j, k] & ~1) | int(binary_msg[idx])
                                        idx += 1
                            else:
                                if idx < len(binary_msg):
                                    pixels[i, j] = (pixels[i, j] & ~1) | int(binary_msg[idx])
                                    idx += 1

                    Image.fromarray(pixels).save(output_path)
                    print(f"{G}[+]{RESET} Message hidden successfully in {C}{output_path}{RESET}")
                    print(f"{Y}[*]{RESET} Image appears identical to human eye")
                except Exception as e:
                    print(f"{R}[-]{RESET} Error: {e}")

            elif choice == "2":
                # استخراج پیام از تصویر
                image_path = input(f"{Y}Image path{R}: {RESET}")

                try:
                    img = Image.open(image_path)
                    pixels = np.array(img)

                    if len(pixels.shape) == 3:
                        height, width, channels = pixels.shape
                    else:
                        height, width = pixels.shape
                        channels = 1

                    binary_msg = ""
                    for i in range(height):
                        for j in range(width):
                            if channels > 1:
                                for k in range(3):
                                    binary_msg += str(pixels[i, j, k] & 1)
                            else:
                                binary_msg += str(pixels[i, j] & 1)

                    # تقسیم به بایت ها
                    message = ""
                    for i in range(0, len(binary_msg), 8):
                        byte = binary_msg[i:i + 8]
                        if byte == '11111111':  # delimiter check
                            break
                        message += chr(int(byte, 2))

                    print(f"\n{G}[+]{RESET} Hidden message found:")
                    print(f"{C}{message}{RESET}")
                except Exception as e:
                    print(f"{R}[-]{RESET} No hidden message found or error: {e}")

            elif choice == "5":
                # Zero-width steganography for text
                zero_width_chars = {
                    '0': '\u200b',  # Zero Width Space
                    '1': '\u200c',  # Zero Width Non-Joiner
                    ' ': '\u200d',  # Zero Width Joiner
                    'delimiter': '\ufeff'  # Zero Width No-Break Space (BOM)
                }

                action = input(f"{Y}Hide or Extract? (h/e){R}: {RESET}")

                if action == "h":
                    cover_text = input(f"{Y}Cover text (visible){R}: {RESET}")
                    secret = input(f"{Y}Secret message{R}: {RESET}")

                    # تبدیل پیام مخفی به باینری و سپس به کاراکترهای zero-width
                    binary = ''.join(format(ord(c), '08b') for c in secret)
                    hidden = ''.join(zero_width_chars['1'] if b == '1' else zero_width_chars['0'] for b in binary)
                    hidden += zero_width_chars['delimiter']

                    # قرار دادن در وسط متن پوشان
                    mid = len(cover_text) // 2
                    result = cover_text[:mid] + hidden + cover_text[mid:]

                    print(f"\n{G}[+]{RESET} Stego text copied (invisible characters embedded):")
                    print(f"{C}{result}{RESET}")
                    print(f"{Y}[!]{RESET} Copy this text carefully - invisible chars included")

                elif action == "e":
                    stego_text = input(f"{Y}Stego text{R}: {RESET}")

                    # استخراج کاراکترهای zero-width
                    binary = ""
                    for char in stego_text:
                        if char == zero_width_chars['1']:
                            binary += '1'
                        elif char == zero_width_chars['0']:
                            binary += '0'
                        elif char == zero_width_chars['delimiter']:
                            break

                    # تبدیل باینری به متن
                    message = ""
                    for i in range(0, len(binary), 8):
                        if i + 8 <= len(binary):
                            byte = binary[i:i + 8]
                            message += chr(int(byte, 2))

                    print(f"\n{G}[+]{RESET} Extracted secret:")
                    print(f"{C}{message}{RESET}")

    def hash_identifier():
        hash_input = input(f"\n{Y}Enter hash{R}: {RESET}")
        length = len(hash_input)

        types = []
        if length == 32:
            types.append("MD5")
        elif length == 40:
            types.append("SHA1")
        elif length == 64:
            types.append("SHA256")
        elif length == 128:
            types.append("SHA512")
        elif length == 16:
            types.append("MySQL (old)")
        elif length == 41 and hash_input.startswith('*'):
            types.append("MySQL 5+")

        print(f"{G}[+]{RESET} Possible hash types:")
        for t in types:
            print(f"    {C}{t}{RESET}")

        # بررسی آنلاین با دیتابیس کرک شده (API hashes.org)
        check = input(f"\n{Y}Check online databases? (y/n){R}: {RESET}")
        if check == 'y':
            print(f"{Y}[*]{RESET} Checking rainbow tables...")
            print(f"{R}[-]{RESET} Not cracked (requires API key for full access)")

    def password_generator():
        length = int(input(f"{Y}Password length{R} [{G}16{R}]: {RESET}") or 16)

        print(f"\n{G}Options:{RESET}")
        upper = input(f"{Y}Uppercase? (y/n){R}: {RESET}") == 'y'
        lower = input(f"{Y}Lowercase? (y/n){R}: {RESET}") == 'y'
        digits = input(f"{Y}Digits? (y/n){R}: {RESET}") == 'y'
        special = input(f"{Y}Special chars? (y/n){R}: {RESET}") == 'y'

        chars = ""
        if upper: chars += string.ascii_uppercase
        if lower: chars += string.ascii_lowercase
        if digits: chars += string.digits
        if special: chars += "!@#$%^&*()_+-=[]{}|;:,.<>?"

        if not chars:
            chars = string.ascii_letters + string.digits

        password = ''.join(secrets.choice(chars) for _ in range(length))
        entropy = length * (len(chars).bit_length() - 1)

        print(f"\n{G}[+]{RESET} Generated password: {C}{password}{RESET}")
        print(f"{Y}[*]{RESET} Entropy: ~{entropy} bits")

        # محاسبه strength
        if entropy < 50:
            print(f"{R}[!]{RESET} Strength: Weak")
        elif entropy < 80:
            print(f"{Y}[!]{RESET} Strength: Medium")
        else:
            print(f"{G}[!]{RESET} Strength: Strong")

    while True:
        print(f"\n{R}╔════════════════════════════════════╗{RESET}")
        print(f"{R}║  {G}CRYPTO & STEGANOGRAPHY{RESET}         {R}║{RESET}")
        print(f"{R}╠════════════════════════════════════╣{RESET}")
        print(f"{R}║  {R}1){RESET} {G}Encryption Tools{RESET}           {R}║{RESET}")
        print(f"{R}║  {R}2){RESET} {G}Steganography{RESET}              {R}║{RESET}")
        print(f"{R}║  {R}3){RESET} {G}Hash Identifier{RESET}          {R}║{RESET}")
        print(f"{R}║  {R}4){RESET} {G}Password Generator{RESET}       {R}║{RESET}")
        print(f"{R}║  {R}5){RESET} {G}File Integrity Check{RESET}     {R}║{RESET}")
        print(f"{R}║  {R}6){RESET} {G}Back to Main{RESET}             {R}║{RESET}")
        print(f"{R}╚════════════════════════════════════╝{RESET}")

        choice = input(f"\n{C}Choose{R} [{G}1-6{R}]: {RESET}")

        if choice == "1":
            encryption_tools()
        elif choice == "2":
            steganography_tools()
        elif choice == "3":
            hash_identifier()
        elif choice == "4":
            password_generator()
        elif choice == "5":
            filepath = input(f"{Y}File path{R}: {RESET}")
            if os.path.exists(filepath):
                sha256 = hashlib.sha256()
                with open(filepath, "rb") as f:
                    for chunk in iter(lambda: f.read(4096), b""):
                        sha256.update(chunk)
                print(f"{G}[+]{RESET} SHA256: {C}{sha256.hexdigest()}{RESET}")
        elif choice == "6":
            break


def forensics_suite():
    blood_banner()

    import os
