            """تغییر حالت API/Local"""
            if self.mode_switch.get() == 1:
                if self.client:
                    self.use_api = True
                    self.current_mode = "API"
                    self.status_label.configure(text="● API Mode (GapGPT)", text_color=COLORS["success"])
